     1→// ============================================================================
     2→// FreeLang Concurrency System - Phase B.1: Send/Sync Traits
     3→// ============================================================================
     4→//
     5→// Rust의 Send/Sync 트레이트를 FreeLang으로 재현
     6→// 목표: 스레드 간 안전한 타입 전달 및 공유를 컴파일 타임에 검증
     7→//
     8→// Send: 소유권을 스레드 간 안전하게 이동 가능
     9→// Sync: 참조를 스레드 간 안전하게 공유 가능
    10→//
    11→// 작성일: 2026-03-02
    12→// 커밋: Phase B.1 (Week 1-2)
    13→
    14→/// Send 트레이트
    15→///
    16→/// T가 Send를 구현하면, T 값을 스레드 간에 안전하게 이동할 수 있습니다.
    17→/// 즉, thread::spawn(move || { ... })에서 T 타입 값을 안전하게 전달할 수 있습니다.
    18→///
    19→/// 기본 규칙:
    20→/// - 모든 필드가 Send이면, 복합 타입도 Send
    21→/// - 스레드 간 소유권 이전 시 데이터 경합 불가능
    22→pub trait Send {
    23→    // 마커 트레이트: 구현 메서드 없음
    24→    // Send라는 것을 선언하는 것만으로 충분
    25→}
    26→
    27→/// Sync 트레이트
    28→///
    29→/// T가 Sync를 구현하면, &T (불변 참조)를 스레드 간에 안전하게 공유할 수 있습니다.
    30→///
    31→/// 기본 규칙:
    32→/// - 모든 필드가 Sync이면, 복합 타입도 Sync
    33→/// - &T를 여러 스레드에서 동시에 접근 가능
    34→pub trait Sync {
    35→    // 마커 트레이트
    36→}
    37→
    38→// ============================================================================
    39→// 원시 타입에 대한 Send 구현
    40→// ============================================================================
    41→
    42→/// 정수형은 모두 Send
    43→impl Send for i8 { }
    44→impl Send for i16 { }
    45→impl Send for i32 { }
    46→impl Send for i64 { }
    47→impl Send for i128 { }
    48→impl Send for u8 { }
    49→impl Send for u16 { }
    50→impl Send for u32 { }
    51→impl Send for u64 { }
    52→impl Send for u128 { }
    53→
    54→/// 부동소수점형도 Send
    55→impl Send for f32 { }
    56→impl Send for f64 { }
    57→
    58→/// 불린형과 문자열 기본형도 Send
    59→impl Send for bool { }
    60→impl Send for char { }
    61→impl Send for str { }
    62→
    63→// ============================================================================
    64→// 원시 타입에 대한 Sync 구현
    65→// ============================================================================
    66→
    67→/// 정수형은 모두 Sync
    68→impl Sync for i8 { }
    69→impl Sync for i16 { }
    70→impl Sync for i32 { }
    71→impl Sync for i64 { }
    72→impl Sync for i128 { }
    73→impl Sync for u8 { }
    74→impl Sync for u16 { }
    75→impl Sync for u32 { }
    76→impl Sync for u64 { }
    77→impl Sync for u128 { }
    78→
    79→/// 부동소수점형도 Sync
    80→impl Sync for f32 { }

