     1→/**
     2→ * FreeLang v4 JIT — Inline Cache (IC)
     3→ *
     4→ * 메서드/프로퍼티 조회를 캐싱하여 반복 타입 체크를 제거합니다.
     5→ *
     6→ * 상태 전이:
     7→ *   uninitialized → monomorphic (타입 1종)
     8→ *   monomorphic   → polymorphic (타입 2~3종)
     9→ *   polymorphic   → megamorphic (타입 4종+) → 캐싱 포기
    10→ *
    11→ * 적용 대상:
    12→ *   - 함수 인자 타입 추론 (ADD i32+i32 등)
    13→ *   - 배열 원소 타입
    14→ *   - 바이너리 연산 타입 특화
    15→ */
    16→
    17→import { ICEntry, CacheState } from "./jit-types";
    18→
    19→// ============================================================
    20→// InlineCache
    21→// ============================================================
    22→
    23→export class InlineCache {
    24→  private entries = new Map<string, ICEntry>();
    25→
    26→  // ── IC 기록 ───────────────────────────────────────────────
    27→
    28→  /**
    29→   * 호출 사이트에 관찰된 타입을 기록
    30→   * @param site  "fnName:pc" 형식 식별자
    31→   * @param type  관찰 타입 ("i32", "f64", "str", ...)
    32→   * @param hit   캐시 히트 여부
    33→   */
    34→  record(site: string, type: string, hit: boolean): void {
    35→    const entry = this.entries.get(site) ?? this.newEntry(site);
    36→
    37→    // 타입 추가 (중복 제외)
    38→    if (!entry.typesSeen.includes(type)) {
    39→      entry.typesSeen.push(type);
    40→    }
    41→
    42→    // 히트/미스 업데이트
    43→    if (hit) entry.hitCount++;
    44→    else      entry.missCount++;
    45→    entry.hitRate = entry.hitCount / (entry.hitCount + entry.missCount);
    46→
    47→    // 상태 전이
    48→    entry.state = this.calcState(entry.typesSeen.length, entry.state);
    49→    this.entries.set(site, entry);
    50→  }
