    95→  // Scheduler — round-robin (SPEC_02 Q7)
    96→  // ============================================================
    97→
    98→  private schedule(): void {
    99→    const SLICE = 1000;
   100→    let current = 0;
   101→
   102→    while (this.actors.some((a) => a.state !== "done")) {
