   176→///
   177→/// # 예제
   178→/// ```
   179→/// assert_eq!(cos(FlValue::Float(0.0)), FlValue::Float(1.0));
   180→/// ```
   181→pub fn cos(value: FlValue) -> Result<FlValue, MathError> {
