   189→/// 탄젠트(tan)를 반환합니다 (라디안 입력).
   190→///
   191→/// # 예제
   192→/// ```
   193→/// assert_eq!(tan(FlValue::Float(0.0)), FlValue::Float(0.0));
   194→/// ```
   195→pub fn tan(value: FlValue) -> Result<FlValue, MathError> {
   196→    match value {
   197→        FlValue::Int(n) => Ok(FlValue::Float((n as f64).tan())),
   198→        FlValue::Float(f) => Ok(FlValue::Float(f.tan())),
   199→        _ => Err(MathError::DomainError("tan requires numeric value".to_string())),
   200→    }
   201→}
   202→
   203→/// 역사인(asin)을 반환합니다 (라디안 반환).
   204→///
   205→/// # 에러
   206→/// - 범위 밖: MathError::DomainError
   207→///
   208→/// # 예제
   209→/// ```
   210→/// assert_eq!(asin(FlValue::Float(0.0)), Ok(FlValue::Float(0.0)));
   211→/// assert_eq!(asin(FlValue::Float(2.0)), Err(MathError::DomainError(_)));
   212→/// ```
   213→pub fn asin(value: FlValue) -> Result<FlValue, MathError> {
   214→    match value {
   215→        FlValue::Int(n) => {
   216→            let f = n as f64;
   217→            if f < -1.0 || f > 1.0 {
   218→                Err(MathError::DomainError("asin domain: [-1, 1]".to_string()))
   219→            } else {
   220→                Ok(FlValue::Float(f.asin()))
   221→            }
   222→        }
   223→        FlValue::Float(f) => {
