	opOrder := []string{
		OpDotProduct.String(),
		OpCosineSimilarity.String(),
		OpL2Distance.String(),
		OpManhattan.String(),
	}

	for _, opName := range opOrder {
		agg, ok := aggMap[opName]
		if !ok {
			continue
		}
		throughput := 0.0
		if agg.AvgTimeNs > 0 {
			throughput = 1e9 / agg.AvgTimeNs
		}
		fmt.Printf("%-20s %10d %10.2f %10.0f %10d %10d %8.0f\n",
			opName,
			agg.TotalCalls,
			agg.ErrorRate,
			agg.AvgTimeNs,
			agg.P50Ns,
			agg.P99Ns,
			throughput,
		)
	}
}

